    C c;

    constructor(C _c) { c = _c; }

    // single public function containing all logic
    function runTest(uint sendAmount) public payable {
        // preconditions: this contract must have enough balance to send
        require(address(this).balance >= sendAmount);
        // read balance before
        uint before = c.balances(address(this));
        // perform deposit by calling receive via sending ether
        // call Deposit() explicitly to follow original contract's public surface
        c.Deposit{value: sendAmount}();
        // read balance after
        uint after = c.balances(address(this));
        // assert that the recorded balance for this contract increased by exactly sendAmount
        assert(after == before + sendAmount);
    }

    // allow funding this contract for the test
    receive() external payable {}
}

