contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // depositAmount is the Ether to send with the Deposit call
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);
        // make a deposit to c from this contract
        c.Deposit{value: depositAmount}();
        // Check that c recorded the deposit under msg.sender (this contract) and not under tx.origin.
        // We can observe balances via the public getter balances(address)
        uint bal_sender = c.balances(address(this));
        uint bal_origin = c.balances(tx.origin);
        // General rule: the amount recorded for the immediate caller equals the deposited amount,
        // and no additional credit appears under tx.origin (i.e., origin's balance did not increase by this depositAmount).
        assert(bal_sender >= depositAmount && bal_sender - depositAmount == 0 && bal_origin < bal_sender);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single test function: deposit funds and check depositor's balance increased by the deposited amount
    function runTest(address depositor, uint256 depositAmount) public payable {
        // ensure this contract has enough eth to forward
        require(msg.value == depositAmount);
        // record balance before
        uint256 before = c.balances(depositor);
        // perform deposit as this contract calling c on behalf of depositor
        // Need to make the deposit come from 'depositor'. We simulate by requiring depositor == address(this)
        // since the test caller cannot change msg.sender of this call. Enforce depositor equals this contract.
        require(depositor == address(this));

        // call Deposit forwarding Ether
        c.Deposit{value: depositAmount}();

        // read balance after
        uint256 after = c.balances(depositor);

        // the balance of the depositor must increase exactly by depositAmount
        assert(after == before + depositAmount);
    }

    // allow contract to receive ETH so it can call runTest with msg.value
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // depositAmount is the ether to send to c; depositor is the tx.originating address (the test caller)
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);
        // Query caller's balance before deposit via public getter
        uint256 before = c.balances(address(this));
        // perform deposit, forwarding depositAmount wei
        c.Deposit{value: depositAmount}();
        // Query caller's balance after deposit via public getter
        uint256 after = c.balances(address(this));
        // General rule: the recorded balance for the caller should increase by at least the sent amount
        assert(after >= before + depositAmount);
    }
    receive() external payable { }
}
